void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85; // Slightly more aggressive reduction
    rephase_limit += 1024; // Smaller increment to trigger rephase more often
    // Update saved phases based on local_best with some randomness
    for (int i = 1; i <= vars; i++) {
        if (rand() % 100 < 70) saved[i] = local_best[i];
        else saved[i] = -local_best[i];
    }
}
